<template>
  <AdminLayout>
    <section class="documents-page">
      <header class="documents-header"><div><p>资料库</p><h1>管理文档</h1></div><label class="upload-button"><input type="file" accept=".pdf,.md,.txt" @change="upload" />＋ 上传文档</label></header>
      <div class="documents-toolbar"><label class="search-box">⌕ <input v-model="query" placeholder="搜索文档" /></label><span>{{ docs.length }} 份文档</span></div>
      <p v-if="note" class="documents-notice">{{ note }}</p>
      <section class="documents-list"><header><span>名称</span><span>状态</span><span>大小</span><span>创建时间</span><span></span></header><article v-for="document in filtered" :key="document.id"><div class="document-name"><i>{{ document.type }}</i><span><b>{{ document.name }}</b><small>{{ document.chunks }} 个片段</small></span></div><span class="status" :class="document.status">{{ statusText(document.status) }}</span><span>{{ document.size }}</span><span>{{ document.time }}</span><span class="row-actions"><button @click="selected = document">查看</button><button @click="remove(document)">删除</button></span></article><div v-if="!filtered.length" class="documents-empty"><i>▤</i><h2>还没有文档</h2><p>上传 PDF、Markdown 或 TXT 文件，随后即可在会话中添加使用。</p><label class="upload-button"><input type="file" accept=".pdf,.md,.txt" @change="upload" />上传第一个文档</label></div></section>
    </section>
    <div v-if="selected" class="detail-backdrop" @click.self="selected = null"><section class="detail-card"><button @click="selected = null">×</button><p>文档详情</p><h2>{{ selected.name }}</h2><dl><div><dt>状态</dt><dd>{{ statusText(selected.status) }}</dd></div><div><dt>片段</dt><dd>{{ selected.chunks }}</dd></div><div><dt>格式</dt><dd>{{ selected.type }}</dd></div></dl></section></div>
  </AdminLayout>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import AdminLayout from '../components/layout/AdminLayout.vue'
import { deleteDocument, fetchDocuments, uploadDocument } from '../services/api'
const docs = ref([]), query = ref(''), note = ref(''), selected = ref(null)
const filtered = computed(() => docs.value.filter(item => item.name.toLowerCase().includes(query.value.toLowerCase())))
const normalize = item => ({ id: item.document_id, name: item.file_name, type: (item.file_type || 'txt').toUpperCase(), size: `${Math.ceil((item.file_size || 0) / 1024)} KB`, time: item.created_at ? new Date(item.created_at).toLocaleDateString() : '刚刚', status: item.parse_status || 'pending', chunks: item.chunk_count || 0 })
const statusText = status => status === 'ready' ? '可检索' : status === 'failed' ? '失败' : '处理中'
async function load() { try { docs.value = ((await fetchDocuments()).documents || []).map(normalize) } catch { note.value = '无法加载资料库，请检查服务连接。' } }
async function upload(event) { const file = event.target.files[0]; event.target.value = ''; if (!file) return; note.value = ''; try { docs.value.unshift(normalize((await uploadDocument(file)).document)); note.value = '文档已上传，正在处理中。' } catch (error) { note.value = `上传失败：${error.message}` } }
async function remove(document) { if (!confirm(`删除“${document.name}”？`)) return; try { await deleteDocument(document.id); docs.value = docs.value.filter(item => item.id !== document.id) } catch (error) { note.value = `删除失败：${error.message}` } }
onMounted(load)
</script>
<style scoped>
.documents-page{width:min(1120px,100%);margin:0 auto;padding:34px clamp(22px,5vw,64px)}.documents-header{display:flex;align-items:center;justify-content:space-between;padding-bottom:28px;border-bottom:1px solid #edf0f3}.documents-header p{margin:0;color:#79869a;font-size:12px}.documents-header h1{margin:4px 0 0;font-size:27px;letter-spacing:-.03em}.upload-button{display:inline-flex;align-items:center;padding:10px 14px;border-radius:8px;background:#1f2937;color:#fff;font-size:12px;font-weight:700;cursor:pointer}.upload-button input{display:none}.documents-toolbar{display:flex;align-items:center;justify-content:space-between;padding:22px 0;color:#8691a0;font-size:12px}.search-box{display:flex;align-items:center;gap:8px;width:min(360px,70%);padding:10px 12px;border:1px solid #e0e5eb;border-radius:9px;color:#7f8996}.search-box input{width:100%;border:0;outline:0;font-size:13px}.documents-notice{padding:10px 12px;border-radius:8px;background:#f1f4f7;color:#4e5d71;font-size:12px}.documents-list{border-top:1px solid #e9edf1}.documents-list>header,.documents-list article{display:grid;grid-template-columns:minmax(260px,1.8fr) .7fr .55fr .7fr 90px;gap:16px;align-items:center;padding:14px 10px;border-bottom:1px solid #edf0f3;font-size:12px}.documents-list>header{color:#7d8795;font-size:11px}.documents-list article:hover{background:#fafbfc}.document-name{display:flex;align-items:center;gap:11px;min-width:0}.document-name i{display:grid;place-items:center;width:34px;height:38px;border:1px solid #e3e7ed;border-radius:7px;color:#e33b3b;font-style:normal;font-size:9px;font-weight:800}.document-name span{display:grid;gap:3px;min-width:0}.document-name b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.document-name small{color:#8b95a3;font-size:10px}.status{justify-self:start;padding:4px 7px;border-radius:5px;background:#f0f2f5;color:#617083;font-size:10px}.status.ready{background:#e9f7d0;color:#4b6a0d}.status.failed{background:#fce9ec;color:#a22e42}.row-actions{display:flex;gap:8px}.row-actions button{border:0;background:transparent;color:#637086;font-size:11px}.row-actions button:last-child{color:#c84a59}.documents-empty{display:grid;justify-items:center;padding:100px 20px;text-align:center}.documents-empty i{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:#eef2f6;color:#536276;font-style:normal}.documents-empty h2{margin:15px 0 5px;font-size:17px}.documents-empty p{max-width:360px;margin:0 0 17px;color:#7e8998;font-size:12px;line-height:1.7}.detail-backdrop{position:fixed;inset:0;z-index:5;display:grid;place-items:center;background:#17203366}.detail-card{width:min(400px,calc(100% - 40px));padding:24px;border-radius:13px;background:#fff}.detail-card>button{float:right;border:0;background:transparent;font-size:22px}.detail-card p{margin:0;color:#7e8998;font-size:11px}.detail-card h2{margin:6px 0 20px;font-size:19px;word-break:break-word}.detail-card dl div{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #edf0f3;font-size:12px}.detail-card dt{color:#7e8998}@media(max-width:760px){.documents-page{padding:22px}.documents-list>header{display:none}.documents-list article{grid-template-columns:1fr auto;gap:10px}.documents-list article>span:nth-child(3),.documents-list article>span:nth-child(4){display:none}.row-actions{grid-column:2}.documents-header{align-items:flex-start;gap:15px}.upload-button{white-space:nowrap}}
</style>
